insert into baton.artifact_schemas (kind, version, schema) values ('pr', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/pr/v1","title":"pr","description":"Validated against the artefact''s meta (a PR has no content blob). Either a number (existing PR) or a branch (the service opens it) is required.","type":"object","required":["repo"],"properties":{"repo":{"type":"string","pattern":"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$"},"number":{"type":"integer","minimum":1},"branch":{"type":"string"},"head_sha":{"type":"string"},"url":{"type":"string"},"title":{"type":"string"},"ci_status":{"type":"string","enum":["pending","success","failure"]},"merged":{"type":"boolean"}},"anyOf":[{"required":["number"]},{"required":["branch"]}],"additionalProperties":true}'::jsonb)
  on conflict (kind, version) do update set schema = excluded.schema;
insert into baton.artifact_schemas (kind, version, schema) values ('db_schema', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/db_schema/v1","title":"db_schema","description":"Tables another role created or changed, so the consumer can code against them without reading the database.","type":"object","required":["tables"],"properties":{"engine":{"type":"string","description":"postgres, mysql, sqlite, mongodb, ..."},"schema":{"type":"string"},"connection_ref":{"type":"string","description":"Where the connection details live (env var name, secret name). Never the secret itself."},"migration_path":{"type":"string"},"tables":{"type":"array","minItems":1,"items":{"type":"object","required":["name","columns"],"properties":{"name":{"type":"string","minLength":1},"purpose":{"type":"string"},"primary_key":{"type":"array","items":{"type":"string"}},"columns":{"type":"array","minItems":1,"items":{"type":"object","required":["name","type"],"properties":{"name":{"type":"string","minLength":1},"type":{"type":"string","minLength":1},"nullable":{"type":"boolean"},"default":{"type":"string"},"references":{"type":"string"},"description":{"type":"string"}}}},"indexes":{"type":"array","items":{"type":"string"}}}}},"notes":{"type":"string"}},"additionalProperties":true}'::jsonb)
  on conflict (kind, version) do update set schema = excluded.schema;
insert into baton.artifact_schemas (kind, version, schema) values ('config', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/config/v1","title":"config","description":"A configuration file or set of keys another role produced, described so the consumer can rely on it.","type":"object","required":["path","keys"],"properties":{"path":{"type":"string","minLength":1,"description":"Where the file lives relative to the repository or system root."},"format":{"type":"string","enum":["json","yaml","toml","env","ini","other"]},"keys":{"type":"array","minItems":1,"items":{"type":"object","required":["name"],"properties":{"name":{"type":"string","minLength":1},"type":{"type":"string"},"default":{},"required":{"type":"boolean"},"description":{"type":"string"}}}},"how_to_load":{"type":"string"},"notes":{"type":"string"}},"additionalProperties":true}'::jsonb)
